        board().then().block();      // warm up, output ignored
        System.out.println("== Flux.combineLatest, slow subscriber");
        t0 = System.nanoTime();
        board().concatMap(v -> Mono.delay(Duration.ofMillis(100)).thenReturn(v), 1)
                .doOnNext(v -> log("-> " + v))
                .blockLast();
        log("done");
    }
}

