fun <T, R> Flow<T>.mapConcurrentOrdered(n: Int, f: suspend (T) -> R): Flow<R> = flow {
    coroutineScope {
        this@mapConcurrentOrdered
            .map { value -> async { f(value) } }   // 4. start the call
            .buffer(n - 2)                          // 5. at most n started and not yet emitted
            .collect { emit(it.await()) }           // 6. emit in input order
    }
}

