fun <T, R> Flow<T>.mergeLanes(lanes: Int, transform: suspend (T) -> Flow<R>): Flow<R> = channelFlow {
    val permits = Semaphore(lanes)
    collect { value ->                          // 1. one coroutine reads the outer flow
        val inner = transform(value)            // 2. ONE VALUE AT A TIME, before a permit
        permits.acquire()                       // 3. wait for a free lane
        launch {                                // 4. one coroutine per lane
            try { inner.collect { send(it) } }  //    results go into one shared channel
            finally { permits.release() }
        }
    }
}
// transform runs in the reading coroutine, so a slow call there blocks the next value from
// being read at all. Only the flow it returns is collected inside a lane.

