// Closest Java equivalent: a reading loop, a Semaphore, and a virtual thread per lane
static <T, R> void mergeLanes(Iterable<T> outer, int lanes, Function<T, Callable<R>> transform,
                              BlockingQueue<R> out) throws InterruptedException {
    Semaphore permits = new Semaphore(lanes);
    for (T value : outer) {                       // 1. one thread reads the outer source
        Callable<R> inner = transform.apply(value); // 2. one value at a time, before a permit
        permits.acquire();                        // 3. wait for a free lane
        Thread.ofVirtual().start(() -> {          // 4. one thread per lane
            try { out.put(inner.call()); }
            catch (Exception e) { Thread.currentThread().interrupt(); }
            finally { permits.release(); }
        });
    }
}
